const x = $input.first().json,
  w = x.workflow ?? {},
  e = x.execution ?? {},
  err = e.error ?? {};
if (typeof w.name !== "string" || !w.name) throw Error("Missing workflow name");
const name = w.name.replace(/[\r\n]+/g, " "),
  v = (x) => (typeof x === "string" && x ? x : "not available");
return [
  {
    json: {
      subject: "Error in workflow: " + name,
      body:
        "Workflow: " +
        w.name +
        "\nExecution URL: " +
        v(e.url) +
        "\nLast node: " +
        v(e.lastNodeExecuted) +
        "\nError message: " +
        v(err.message) +
        "\nStack trace: " +
        v(err.stack),
    },
  },
];
